// Pattern 4: Workflow Immune System Diagnostic Engine
const errData = $input.first().json;

const errorMessage = errData.execution?.error?.message || errData.message || 'Unknown error';
const workflowName = errData.workflow?.name || 'Unknown workflow';
const lastNode = errData.execution?.lastNodeExecuted || 'Unknown node';

// Classify failure nature
let classification = 'STRUCTURAL';
let retryAllowed = false;

if (/429|timeout|ECONNRESET|ETIMEDOUT|rate limit/i.test(errorMessage)) {
  classification = 'TRANSIENT';
  retryAllowed = true;
} else if (/unauthorized|forbidden|401|403|token|key/i.test(errorMessage)) {
  classification = 'AUTH_CREDENTIAL_DEFECT';
  retryAllowed = false;
} else if (/schema|validation|missing field|syntax/i.test(errorMessage)) {
  classification = 'STRUCTURAL_SCHEMA_DEFECT';
  retryAllowed = false;
}

return [{
  json: {
    incident_id: 'INC-' + Date.now(),
    workflow_name: workflowName,
    failed_node: lastNode,
    error_message: errorMessage,
    classification,
    retry_allowed: retryAllowed,
    timestamp: new Date().toISOString(),
    recommendation: retryAllowed ? 'Bounded exponential backoff' : 'Route to DLQ; dispatch repair via OMP / AGY'
  }
}];

// Dead-Letter Queue (DLQ) Envelope Formatter
const item = $input.first().json;

return [{
  json: {
    dlq_record: {
      ...item,
      quarantine_status: 'QUARANTINED',
      dlq_location: 'MEMORY_LOG',
      continuation_cursor: `REPAIR_WORKFLOW:${item.workflow_name}:${item.failed_node}`
    }
  }
}];

